<template>
 <article class="radar-card" :class="{'radar-card--compact':compact,'radar-card--unavailable':item.status!=='ok'}" :aria-label="item.name">
  <header><h3 :title="item.indexName??item.name">{{item.name}}</h3><time v-if="showDate&&item.date" :title="item.date">{{item.date.slice(5)}}</time></header>
  <div class="radar-card__axes"><div v-for="axis in axes" :key="axis.key" class="radar-score" :class="axis.key"><span>{{axis.label}}</span><strong>{{item[axis.key]??'—'}}</strong><i aria-hidden="true"><b :style="{width:`${item[axis.key]??0}%`}"/></i></div></div>
  <div v-if="!compact&&comparisons.length" class="radar-card__changes"><div class="radar-card__change-head"><span>变化 / 分</span><span v-for="axis in axes" :key="axis.key">{{axis.label}}</span></div><div v-for="c in comparisons" :key="c.key"><span>{{c.label}}</span><span v-for="axis in axes" :key="axis.key">{{delta(item[c.key]?.[axis.key])}}</span></div></div>
  <p v-else-if="compact&&item.change5d?.strength!==null&&item.change5d?.strength!==undefined" class="radar-card__direction">5日强度 <strong>{{delta(item.change5d.strength)}}</strong></p>
  <div v-if="!compact&&item.history.length>1" class="radar-card__history"><svg viewBox="0 0 300 44" preserveAspectRatio="none" role="img" :aria-label="`${item.name}近${item.history.length}期强度轨迹`"><path :d="trajectory(item.history)" fill="none" stroke="currentColor" stroke-width="1.5" vector-effect="non-scaling-stroke"/></svg><span>{{item.history[0]?.date}} — {{item.history.at(-1)?.date}}</span></div>
  <details class="radar-card__evidence"><summary>依据</summary><p>{{item.indexName??item.name}}<template v-if="item.code"> · {{item.code}}</template><template v-if="item.date"> · {{item.date}}</template></p><p v-if="item.return5!==null">5期收益 {{item.return5.toFixed(2)}}%<template v-if="item.volumeRatio!==null"> · 量比 {{item.volumeRatio.toFixed(2)}}倍</template></p><div v-for="axis in axes" :key="axis.key" class="radar-card__factors"><h4>{{axis.label}}</h4><div v-for="f in item.factors[axis.key]??[]" :key="f.key"><span>{{f.label}}</span><span>{{factorValue(f)}} · 权重{{f.weight}}%</span></div></div></details>
 </article>
</template>
<script setup lang="ts">
import {computed} from 'vue'
import type {Axis,Factor,RadarObject,ScorePoint} from '@/features/market-radar/model.mjs'
const props=defineProps<{item:RadarObject;compact?:boolean;showDate?:boolean}>()
const axes:{key:Axis;label:string}[]=[{key:'strength',label:'强度'},{key:'heat',label:'热度'},{key:'risk',label:'风险'}]
const comparisons=computed(()=>([{key:'change1d',label:'1日'},{key:'change5d',label:'5日'}] as const).filter(c=>props.item[c.key]&&axes.some(axis=>props.item[c.key]?.[axis.key]!==null)))
const delta=(n:number|null|undefined)=>n===null||n===undefined?'—':(n>0?'+':'')+n
const factorValue=(f:Factor)=>f.value===null?'—':f.value.toFixed(f.unit==='倍'?2:1)+f.unit
function trajectory(points:ScorePoint[]){let pen=false;return points.map((p,i)=>{if(p.strength===null){pen=false;return ''}const text=`${pen?'L':'M'}${(3+i/Math.max(1,points.length-1)*294).toFixed(1)},${(41-p.strength*.38).toFixed(1)}`;pen=true;return text}).join(' ')}
</script>
<style scoped>
.radar-card{min-width:0;border:1px solid #203a4e;border-radius:7px;background:#0c1b2b;padding:12px}.radar-card header{display:flex;align-items:center;justify-content:space-between;gap:8px}.radar-card h3{margin:0;color:#bed9e9;font-size:13px;font-weight:600}.radar-card time{font-size:9px;color:#718fa5}.radar-card__axes{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:9px;margin-top:12px}.radar-score>span{display:block;font-size:10px;color:#89a8bd}.radar-score strong{font:30px ui-monospace,monospace;color:#77c9df;display:block;line-height:1.5}.radar-score.heat strong{color:#d3ba70}.radar-score.risk strong{color:#de8e94}.radar-score i{height:3px;background:#1f3447;display:block;margin-bottom:8px}.radar-score b{height:100%;display:block;background:#58b7cf}.radar-score.heat b{background:#baa15f}.radar-score.risk b{background:#b96d75}.radar-card__changes>div{display:grid;grid-template-columns:1.1fr repeat(3,1fr);gap:5px;font-size:10px;border-top:1px solid #20374a;padding:5px 0;color:#a6bdce}.radar-card__changes>div>span:not(:first-child){text-align:right}.radar-card__changes .radar-card__change-head{color:#6d8ba1;font-size:9px}.radar-card__history{margin-top:7px;color:#5bb9d1}.radar-card__history svg{width:100%;height:44px;display:block}.radar-card__history>span{font-size:8px;color:#668ba2}.radar-card__evidence{margin-top:8px;border-top:1px solid #20394b;padding-top:6px;font-size:10px;color:#829fb6}.radar-card__evidence summary{cursor:pointer}.radar-card__evidence p{font-size:10px;line-height:1.7;margin:8px 0}.radar-card__factors h4{font-weight:500;color:#9fbccd;font-size:10px;margin:9px 0 4px}.radar-card__factors>div{display:flex;justify-content:space-between;gap:8px;flex-wrap:wrap;font-size:9px;padding:4px 0;border-bottom:1px solid #1b3041}.radar-card--compact{padding:10px}.radar-card--compact .radar-score strong{font-size:22px}.radar-card--compact .radar-card__axes{gap:7px;margin-top:9px}.radar-card__direction{font-size:9px;color:#759bb2;margin:3px 0 0}.radar-card__direction strong{font:11px ui-monospace,monospace;color:#a7cbdc}.radar-card--unavailable .radar-score strong{color:#688095}
</style>
